1	import { useEffect, useState } from 'react';
2	import { useParams, useNavigate } from 'react-router-dom';
3	import { supabase } from '../../lib/supabase';
4	import { WalletService } from '../../services/walletService';
5	import { logError } from '../../lib/logger';
6	import { ArrowLeft, Star, MapPin, Clock, ChevronRight, CheckCircle, XCircle, MessageSquare, Play, Square, Loader2 } from 'lucide-react';
7	import { formatDistanceToNow } from 'date-fns';
8	import { ptBR } from 'date-fns/locale';
9	import { useToast } from '../../contexts/ToastContext';
10	import JobLifecycleStepper from '../../components/JobLifecycleStepper';
11	import EscrowStatusBadge from '../../components/EscrowStatusBadge';
12	
13	export default function CompanyJobCandidates() {
14	    const { id } = useParams();
15	    const navigate = useNavigate();
16	    interface WorkerProfile {
17	        id: string;
18	        full_name: string;
19	        avatar_url?: string;
20	        city?: string;
21	        level?: number;
22	        rating_average?: number;
23	        reviews_count?: number;
24	        tags?: string[];
25	    }
26	
27	    interface Application {
28	        id: string;
29	        job_id: string;
30	        worker_id: string;
31	        status: string;
32	        cover_letter?: string;
33	        created_at: string;
34	        worker?: WorkerProfile;
35	        job?: { title: string };
36	        worker_checkin_at?: string;
37	        worker_checkout_at?: string;
38	        company_checkin_confirmed_at?: string;
39	        company_checkout_confirmed_at?: string;
40	    }
41	
42	    const [candidates, setCandidates] = useState<Application[]>([]);
43	    const [jobTitle, setJobTitle] = useState('');
44	    const [loading, setLoading] = useState(true);
45	    const [ratingModalOpen, setRatingModalOpen] = useState(false);
46	    const [selectedApp, setSelectedApp] = useState<Application | null>(null);
47	    const [rating, setRating] = useState(5);
48	    const [comment, setComment] = useState('');
49	    const [submittingReview, setSubmittingReview] = useState(false);
50	    const [confirmingCheckin, setConfirmingCheckin] = useState<string | null>(null);
51	    const [companyBalance, setCompanyBalance] = useState<number | null>(null);
52	    const [confirmDeliveryApp, setConfirmDeliveryApp] = useState<Application | null>(null);
53	    const [releasing, setReleasing] = useState(false);
54	    const [escrowStatusMap, setEscrowStatusMap] = useState<Record<string, 'reserved' | 'released'>>({});
55	    const { addToast } = useToast();
56	
57	    useEffect(() => {
58	        if (id) fetchCandidates();
59	    // eslint-disable-next-line react-hooks/exhaustive-deps -- fetchCandidates usa state setters estaveis, so precisa re-executar quando id muda
60	    }, [id]);
61	
62	    const fetchCandidates = async () => {
63	        try {
64	            const { data: { user } } = await supabase.auth.getUser();
65	            if (!user) { navigate('/login'); return; }
66	
67	            // Fetch Job Title (only if owned by this company)
68	            const { data: job, error: jobError } = await supabase.from('jobs').select('title').eq('id', id).eq('company_id', user.id).single();
69	            if (jobError || !job) { navigate('/company/jobs'); return; }
70	            setJobTitle(job.title);
71	
72	            // Fetch Applications with Worker Profile (using 'workers' table now)
73	            const { data, error } = await supabase
74	                .from('applications')
75	                .select(`
76	                    *,
77	                    worker:workers(*),
78	                    worker_checkin_at,
79	                    worker_checkout_at,
80	                    company_checkin_confirmed_at,
81	                    company_checkout_confirmed_at
82	                `)
83	                .eq('job_id', id)
84	                .order('created_at', { ascending: false });
85	
86	            if (error) throw error;
87	            setCandidates(data || []);
88	
89	            // Fetch escrow status per application for this job
90	            const { data: escrowRows } = await supabase
91	                .from('escrow_transactions')
92	                .select('application_id, status')
93	                .eq('job_id', id);
94	            const statusMap: Record<string, 'reserved' | 'released'> = {};
95	            (escrowRows || []).forEach((row) => {
96	                if (row.application_id && (row.status === 'reserved' || row.status === 'released')) {
97	                    statusMap[row.application_id] = row.status;
98	                }
99	            });
100	            setEscrowStatusMap(statusMap);
101	
102	            // Fetch company balance to guard the "Contratar" button (AC-7)
103	            const wallet = await WalletService.getOrCreateWallet(user.id, 'company');
104	            setCompanyBalance(wallet ? wallet.balance : null);
105	        } catch (error) {
106	            logError('CompanyJobCandidates', error);
107	        } finally {
108	            setLoading(false);
109	        }
110	    };
111	
112	    const handleUpdateStatus = async (appId: string, newStatus: string) => {
113	        const { error } = await supabase.from('applications').update({ status: newStatus }).eq('id', appId);
114	
115	        if (error) {
116	            logError('CompanyJobCandidates: handleUpdateStatus', error);
117	            addToast('Erro ao atualizar status do candidato.', 'error');
118	            return;
119	        }
120	
121	        if (newStatus === 'hired') {
122	            addToast('Candidato contratado! O job agora está em andamento.', 'success');
123	        }
124	        fetchCandidates();
125	    };
126	
127	    const handleConfirmDelivery = async (app: Application) => {
128	        setReleasing(true);
129	        // Slice 2: ramifica por escrow.kind — postpaid captura o hold no cartao; prepaid libera escrow legado.
130	        const result = await WalletService.releaseOrCaptureEscrow(app.job_id, app.worker_id);
131	        if (!result.success) {
132	            addToast('Erro ao liberar pagamento. Tente novamente.', 'error');
133	            setReleasing(false);
134	            return;
135	        }
136	        const { error: updateError } = await supabase.from('applications').update({ status: 'completed' }).eq('id', app.id);
137	        if (updateError) {
138	            addToast('Pagamento liberado, mas houve erro ao atualizar status. Contate o suporte.', 'error');
139	            setReleasing(false);
140	            setConfirmDeliveryApp(null);
141	            fetchCandidates();
142	            return;
143	        }
144	        setConfirmDeliveryApp(null);
145	        setReleasing(false);
146	        addToast('Entrega confirmada! Pagamento liberado ao profissional.', 'success');
147	        fetchCandidates();
148	    };
149	
150	    const handleSubmitReview = async () => {
151	        if (!selectedApp) return;
152	        setSubmittingReview(true);
153	
154	        try {
155	            const { data: { user } } = await supabase.auth.getUser();
156	            if (!user) throw new Error('Not authenticated');
157	
158	            // Update Application Status to reviewed (best-effort, already completed)
159	            const { error: appError } = await supabase
160	                .from('applications')
161	                .update({ status: 'completed' })
162	                .eq('id', selectedApp.id);
163	
164	            if (appError) {
165	                logError('CompanyJobCandidates: app status update failed', appError);
166	            }
167	
168	            // Create Review (non-critical, best-effort)
169	            const { error: reviewError } = await supabase.from('reviews').insert({
170	                job_id: selectedApp.job_id,
171	                reviewer_id: user.id,
172	                reviewed_id: selectedApp.worker_id,
173	                rating: rating,
174	                comment: comment,
175	                created_at: new Date().toISOString()
176	            });
177	
178	            if (reviewError) {
179	                logError('CompanyJobCandidates: review error', reviewError);
180	                if (reviewError.code === '23505') {
181	                    addToast('Você já avaliou este profissional para este job.', 'error');
182	                } else {
183	                    addToast('Erro ao salvar avaliação. Tente novamente.', 'error');
184	                }
185	                setSubmittingReview(false);
186	                setRatingModalOpen(false);
187	                fetchCandidates();
188	                return;
189	            }
190	
191	            addToast('Avaliação enviada com sucesso!', 'success');
192	
193	            setRatingModalOpen(false);
194	            setRating(5);
195	            setComment('');
196	            fetchCandidates();
197	
198	        } catch (error) {
199	            logError('CompanyJobCandidates', error);
200	            addToast('Erro ao enviar avaliação.', 'error');
201	        } finally {
202	            setSubmittingReview(false);
203	        }
204	    };
205	
206	    const handleChat = async (app: Application) => {
207	        try {
208	            // Check if conversation exists
209	            const { data: existingConvs } = await supabase
210	                .from('Conversation')
211	                .select('id')
212	                .eq('application_uuid', app.id)
213	                .limit(1);
214	
215	            if (existingConvs && existingConvs.length > 0) {
216	                navigate(`/company/messages?conversation=${existingConvs[0].id}`);
217	            } else {
218	                // Create new conversation
219	                const newConvId = crypto.randomUUID();
220	                const { error } = await supabase
221	                    .from('Conversation')
222	                    .insert({
223	                        id: newConvId,
224	                        application_uuid: app.id,
225	                        islocked: false
226	                    });
227	
228	                if (error) throw error;
229	                navigate(`/company/messages?conversation=${newConvId}`);
230	            }
231	        } catch (error) {
232	            logError('CompanyJobCandidates', error);
233	            addToast('Erro ao iniciar conversa.', 'error');
234	        }
235	    };
236	
237	    const handleConfirmCheckin = async (appId: string) => {
238	        setConfirmingCheckin(appId);
239	        try {
240	            const { error } = await supabase
241	                .from('applications')
242	                .update({ company_checkin_confirmed_at: new Date().toISOString() })
243	                .eq('id', appId);
244	
245	            if (error) throw error;
246	            fetchCandidates();
247	        } catch (error) {
248	            logError('CompanyJobCandidates', error);
249	            addToast('Erro ao confirmar check-in.', 'error');
250	        } finally {
251	            setConfirmingCheckin(null);
252	        }
253	    };
254	
255	    const handleConfirmCheckout = async (appId: string) => {
256	        setConfirmingCheckin(appId);
257	        try {
258	            const { error } = await supabase
259	                .from('applications')
260	                .update({ company_checkout_confirmed_at: new Date().toISOString() })
261	                .eq('id', appId);
262	
263	            if (error) throw error;
264	            fetchCandidates();
265	        } catch (error) {
266	            logError('CompanyJobCandidates', error);
267	            addToast('Erro ao confirmar check-out.', 'error');
268	        } finally {
269	            setConfirmingCheckin(null);
270	        }
271	    };
272	
273	    const computeSteps = (app: Application) => {
274	        const checkinComplete = !!(app.worker_checkin_at && app.company_checkin_confirmed_at);
275	        const checkinActive = !!(app.worker_checkin_at && !app.company_checkin_confirmed_at);
276	        const checkoutComplete = !!(app.worker_checkout_at && app.company_checkout_confirmed_at);
277	        const checkoutActive = !!(app.worker_checkout_at && !app.company_checkout_confirmed_at);
278	
279	        return [
280	            { label: 'Contratado', status: 'complete' as const },
281	            {
282	                label: 'Chegada',
283	                status: checkinComplete ? 'complete' as const : checkinActive ? 'active' as const : 'pending' as const
284	            },
285	            {
286	                label: 'Saída',
287	                status: checkoutComplete ? 'complete' as const : checkoutActive ? 'active' as const : 'pending' as const
288	            },
289	            {
290	                label: 'Entrega',
291	                status: app.status === 'completed' ? 'complete' as const : 'pending' as const
292	            }
293	        ];
294	    };
295	
296	    return (
297	        <div className="max-w-4xl mx-auto animate-in fade-in slide-in-from-bottom-4 duration-500 pb-20">
298	            {/* Header */}
299	            <div className="flex items-center justify-between mb-8">
300	                <div>
301	                    <button onClick={() => navigate('/company/jobs')} className="flex items-center gap-2 text-gray-400 font-bold hover:text-black transition-colors mb-2">
302	                        <ArrowLeft size={16} strokeWidth={3} /> Voltar para Vagas
303	                    </button>
304	                    <h1 className="text-3xl font-black uppercase tracking-tighter">Candidatos</h1>
305	                    <p className="text-gray-500 font-bold">{jobTitle} • {candidates.length} aplicações</p>
306	                </div>
307	            </div>
308	
309	            {/* Candidates List */}
310	            <div className="space-y-4">
311	                {loading ? (
312	                    <div className="space-y-4 animate-pulse">
313	                        {[...Array(3)].map((_, i) => (
314	                            <div key={i} className="bg-gray-200 rounded-xl h-32" />
315	                        ))}
