42	function formatCardNumber(value: string): string {
43	  return value
44	    .replace(/\D/g, '')
45	    .slice(0, 16)
46	    .replace(/(.{4})/g, '$1 ')
47	    .trim();
48	}
49	
50	function formatCpfCnpj(value: string): string {
51	  const digits = value.replace(/\D/g, '').slice(0, 14);
52	  if (digits.length <= 11) {
53	    return digits
54	      .replace(/(\d{3})(\d)/, '$1.$2')
55	      .replace(/(\d{3})(\d)/, '$1.$2')
56	      .replace(/(\d{3})(\d{1,2})$/, '$1-$2');
57	  }
58	  return digits
59	    .replace(/(\d{2})(\d)/, '$1.$2')
60	    .replace(/(\d{3})(\d)/, '$1.$2')
61	    .replace(/(\d{3})(\d)/, '$1/$2')
62	    .replace(/(\d{4})(\d{1,2})$/, '$1-$2');
63	}
64	
65	function formatPhone(value: string): string {
66	  const digits = value.replace(/\D/g, '').slice(0, 11);
67	  if (digits.length <= 10) {
68	    return digits.replace(/(\d{2})(\d{4})(\d{0,4})/, '($1) $2-$3').trim();
69	  }
70	  return digits.replace(/(\d{2})(\d{5})(\d{0,4})/, '($1) $2-$3').trim();
71	}
72	
73	function formatCep(value: string): string {
74	  return value.replace(/\D/g, '').slice(0, 8).replace(/(\d{5})(\d{0,3})/, '$1-$2').trim();
75	}
